    internal InnerAutoMLJobAutoMLJobCompletionCriteriaFactory CompletionCriteriaFactory { get; set; }

    protected override Humidifier.SageMaker.AutoMLJobTypes.TextGenerationJobConfig Create()
    {
        var textGenerationJobConfigResult = CreateTextGenerationJobConfig();
        factoryAction?.Invoke(textGenerationJobConfigResult);

        return textGenerationJobConfigResult;
    }

    private Humidifier.SageMaker.AutoMLJobTypes.TextGenerationJobConfig CreateTextGenerationJobConfig()
    {
        var textGenerationJobConfigResult = new Humidifier.SageMaker.AutoMLJobTypes.TextGenerationJobConfig();

        return textGenerationJobConfigResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.AutoMLJobTypes.TextGenerationJobConfig result)
    {
        base.CreateChildren(result);

        result.ModelAccessConfig ??= ModelAccessConfigFactory?.Build();
        result.CompletionCriteria ??= CompletionCriteriaFactory?.Build();
    }

} // End Of Class

